package com.greenlink.security;
import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final CustomUserDetailsService users; public JwtAuthenticationFilter(JwtService jwt,CustomUserDetailsService users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String token=h.substring(7); try{if(jwt.isValid(token)){String id=jwt.extractUserId(token); if(SecurityContextHolder.getContext().getAuthentication()==null){var p=users.loadById(id); var a=new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()); SecurityContextHolder.getContext().setAuthentication(a);}}}catch(Exception ignored){}} chain.doFilter(req,res);} }
